// <auto-generated/>
using SQLQueryBuilder.Helper;
using SQLQueryBuilder.Interface;
using SQLQueryBuilder.Model.SQL_Expression;
using SQLQueryBuilder.SQLEnum;
using System.Text;

namespace SQLBuilderShowcase.Pages
{
    public partial class ASTVisualizer : IASTVisitor
    {
        private SQLBuilderHelper _helper = new SQLBuilderHelper();
        private IASTTraverser _traverser;
        private StringBuilder _sb = new();
        private string _input = "5<1 AND 10 > 11 OR 3 = 2";
        protected override void OnInitialized()
        {
            _traverser = _helper.ASTWalkerBuiler(this);
            _traverser.Walk(_helper.BuildExpression(_input));
        }

        public void OnBinary(BinaryExpression binary)
        {
            Div("d-flex flex-column gap-3", () =>
            {
                Div("fw-bold fs-5 text-muted", () =>
                {
                    _sb.Append($"Binary {binary.Operator}");
                });

                Div("d-flex gap-3", () =>
                {
                    Div("flex-shrink-0", () =>
                    {
                        Div("card", () =>
                        {
                            Div("card-header bg-info-subtle", () => _sb.Append("Left"));
                            Div("card-body", () => _traverser.Walk(binary.Left));
                        });
                    });

                    Div("flex-shrink-0", () =>
                    {
                        Div("card", () =>
                        {
                            Div("card-header bg-info-subtle", () => _sb.Append("Right"));
                            Div("card-body", () => _traverser.Walk(binary.Right));
                        });
                    });
                });
            });
        }

        public void OnLiteral(LiteralExpression literal)
        {
            Action header;
            string cardHeader = "card-header bg-info-subtle";
            switch (literal.Type)
            {
                case SQLLiteralType.Money:
                    header = () => Div(cardHeader, () => _sb.Append("Money Literal"));
                    break;

                case SQLLiteralType.BinaryLiteral:
                    header = () => Div(cardHeader, () => _sb.Append("Binary Literal"));
                    break;

                case SQLLiteralType.UnicodeString:
                    header = () => Div(cardHeader, () => _sb.Append("Unicode Literal"));
                    break;

                case SQLLiteralType.String:
                    header = () => Div(cardHeader, () => _sb.Append("String Literal"));
                    break;

                case SQLLiteralType.Scientific:
                    header = () => Div(cardHeader, () => _sb.Append("Scientific Literal"));
                    break;

                case SQLLiteralType.Decimal:
                    header = () => Div(cardHeader, () => _sb.Append("Decimal Literal"));
                    break;

                case SQLLiteralType.Integer:
                    header = () => Div(cardHeader, () => _sb.Append("Integer Literal"));
                    break;

                case SQLLiteralType.Date:
                    header = () => Div(cardHeader, () => _sb.Append("Date Literal"));
                    break;

                case SQLLiteralType.Time:
                    header = () => Div(cardHeader, () => _sb.Append("Time Literal"));
                    break;

                case SQLLiteralType.Datetime:
                    header = () => Div(cardHeader, () => _sb.Append("Datetime Literal"));
                    break;

                case SQLLiteralType.Null:
                    header = () => Div(cardHeader, () => _sb.Append("Null Literal"));
                    break;

                default:
                    header = () => Div(cardHeader, () => _sb.Append("Null Literal"));
                    break;
            }

            Div("card", () =>
            {
                header();
                Div("card-body", () => _sb.Append(literal.Value));
            });
        }
        private void Div(string cssClass, Action content)
        {
            _sb.Append($"<div class=\"{cssClass}\">");

            content();

            _sb.Append("</div>");
        }
    }
}
